protected int findByte(byte value, int pos) {
    // Ensure the buffer exists and has elements
    if (buffer == null || buffer.length == 0) {
        return -1;
    }

    // Adjust starting position if it is negative
    if (pos < 0) {
        pos = 0;
    }

    // If starting position is beyond the buffer, nothing to search
    if (pos >= buffer.length) {
        return -1;
    }

    // Search for the byte value starting from the specified position
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i; // Return the index where the byte was found
        }
    }

    // Byte not found in the buffer
    return -1;
}

