public long readLong(final int offset){
    // Validate the offset to ensure we can read 8 bytes without going out of bounds
    if (offset < 0 || offset + 8 > b.length) {
        throw new IllegalArgumentException("Invalid offset for reading long: " + offset);
    }
    // Combine the 8 bytes into a signed long value (big-endian)
    return ((long) b[offset]     & 0xFFL) << 56
         | ((long) b[offset + 1] & 0xFFL) << 48
         | ((long) b[offset + 2] & 0xFFL) << 40
         | ((long) b[offset + 3] & 0xFFL) << 32
         | ((long) b[offset + 4] & 0xFFL) << 24
         | ((long) b[offset + 5] & 0xFFL) << 16
         | ((long) b[offset + 6] & 0xFFL) << 8
         | ((long) b[offset + 7] & 0xFFL);
}

