public void put(LoggingEvent o){
    if (o == null) {
        return; // nothing to add
    }
    if (buffer == null || buffer.length == 0) {
        return; // no storage available
    }
    try {
        buffer[tail] = o;
        tail = (tail + 1) % buffer.length;
    } catch (Exception e) {
        // silently drop the event if any runtime issue occurs
    }
}

