                "index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < end) {
