            if (low >= 0xDC00 && low <= 0xDFFF) {
                size += 4;
                i++; // skip low surrogate
                continue;
            }
            // high surrogate without low surrogate
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

