        throw new Exception("Target type is not Character");
    }

    // Null values are converted to null
    if (value == null) {
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }

    // String of length 1
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0); // autoboxes to Character
        } else {
            throw new Exception("Cannot convert String to Character: length != 1");
        }
    }

    // Number to char (within Unicode range)
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= 0 && intVal <= 0xFFFF) {
            return (char) intVal; // autoboxes to Character
        } else {
            throw new Exception("Number value out of char range");
        }
    }

    // Unsupported types
    throw new Exception("Unsupported type for conversion to Character: " + value.getClass().getName());
}

