        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i += 2;
                break;
            case 't':
                sb.append('\t');
                i += 2;
                break;
            case 'b':
                sb.append('\b');
                i += 2;
                break;
            case 'f':
                sb.append('\f');
                i += 2;
                break;
            case 'r':
                sb.append('\r');
                i += 2;
                break;
            case '\'':
                sb.append('\'');
                i += 2;
                break;
            case '\"':
                sb.append('\"');
                i += 2;
                break;
            case '\\':
                sb.append('\\');
                i += 2;
                break;
            case 'u':
                // Unicode escape: \uXXXX
