        java.util.Set<Node> visited = new java.util.HashSet<>();
        while (true) {
            Node current = circ.getNode();
            if (current == null) {
                throw new IllegalStateException("Circulator returned null node");
            }

            // If the current node satisfies the predicate, return this circulator
            if (predicate.test(current)) {
                return circ;
            }

            // If we have reached the stop node, return this circulator
            if (current.equals(stop)) {
                return circ;
            }

            // If we have already visited this node, we are in a loop; break out
            if (!visited.add(current)) {
                break;
            }

            // Move to the next node in the specified direction
            circ = (dir == 0) ? circ.next() : circ.prev();
            if (circ == null) {
                throw new IllegalStateException("Circulator traversal returned null");
            }
        }

        // If we exited the loop without finding the predicate or stop node,
        // attempt to locate the stop node explicitly
        circ = new OuterFaceCirculator(start, dir);
        while (true) {
            Node current = circ.getNode();
            if (current == null) {
                break;
            }
            if (current.equals(stop)) {
                return circ;
            }
            circ = (dir == 0) ? circ.next() : circ.prev();
            if (circ.getNode().equals(start)) {
                break;
            }
        }

        // Fallback: return the circulator at the start node
        return circ;

