public int compare(Object aObj1, Object aObj2) {
    // Handle reference equality and nulls first
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1; // null is considered less than any non-null
    }
    if (aObj2 == null) {
        return 1; // any non-null is greater than null
    }

    // If both objects implement Comparable, try to compare them
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            // The objects are not mutually comparable
            throw new ClassCastException(
                "Objects are not mutually comparable: " + aObj1.getClass() + " vs " + aObj2.getClass()
            );
        }
    }

    // Fallback: compare string representations
    try {
        String s1 = aObj1.toString();
        String s2 = aObj2.toString();
        return s1.compareTo(s2);
    } catch (Exception e) {
        // If toString() throws, treat objects as equal
        return 0;
    }
}

public void removeAppender(String name) {
    if (name == null || name.trim().isEmpty()) {
        throw new IllegalArgumentException("Appender name must not be null or empty");
    }
    if (this.appenders == null) {
        throw new IllegalStateException("Appender list is not initialized");
    }
    for (int i = 0; i < this.appenders.size(); i++) {
        Appender appender = this.appenders.get(i);
        if (name.equals(appender.getName())) {
            this.appenders.remove(i);
            return;
        }
    }
}

