    if (bounds == null) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    int[] temp = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        long v = (val == null) ? 0L : val.longValue();
        total += v;
        temp[i] = (int) total;
    }
    for (int i = 0; i < n; i++) {
        suffix.add(temp[i]);
    }
    return new Pair<>(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int n = arr.length;
    if (from < 0 || to < 0 || from >= n || to >= n) {
        throw new IllegalArgumentException("Indices out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to to index");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Validate input
    if (list == null || list == this || list.size == 0) {
        return;
    }

    // If this list is empty, simply adopt the other list's nodes
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Link the tail of this list to the head of the other list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update size
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

