public static Type resolveBound(TypeVariable<?> typeVariable) {
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds == null || bounds.length == 0) {
            return Unknown.class;
        }
        Type bound = bounds[0];
        // Resolve recursively if the bound itself is a TypeVariable
        while (bound instanceof TypeVariable) {
            TypeVariable<?> tv = (TypeVariable<?>) bound;
            Type[] tvBounds = tv.getBounds();
            if (tvBounds == null || tvBounds.length == 0) {
                return Unknown.class;
            }
            bound = tvBounds[0];
        }
        return bound != null ? bound : Unknown.class;
    } catch (Exception e) {
        return Unknown.class;
    }
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // A null or empty set is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Check every unordered pair of distinct vertices
    for (V v1 : vertices) {
        if (v1 == null) {
            throw new IllegalArgumentException("Vertex set contains null");
        }
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (v2 == null) {
                throw new IllegalArgumentException("Vertex set contains null");
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

