public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    // If relativePath is empty or just ".", return the original path
    if (relativePath.isEmpty() || relativePath.equals(".")) {
        return path;
    }

    // Determine if the original path is absolute
    boolean isAbsolute = path.startsWith("/");

    // Split the original path into components, ignoring empty parts
    String[] pathParts = path.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    for (String part : pathParts) {
        if (!part.isEmpty()) {
            stack.addLast(part);
        }
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip empty or current directory references
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else {
                // If the path is absolute, we cannot go above root
                // If relative, we simply ignore further ".." beyond the start
                // (could also choose to keep ".." but here we ignore)
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If the result is empty, return "." for relative paths or "/" for absolute root
    if (result.length() == 0) {
        return isAbsolute ? "/" : ".";
    }

    return result.toString();
}

