public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSlash = filename.lastIndexOf('/');
    int lastBackslash = filename.lastIndexOf('\\');
    int lastSeparator = Math.max(lastSlash, lastBackslash);
    return (lastDot > lastSeparator) ? lastDot : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // If threshold is non-positive, consider the metric expired
        if (expiredThreshold <= 0) {
            return true;
        }
        long now = System.currentTimeMillis();
        // If the timestamp is in the future, it cannot be expired yet
        if (now < timestamp) {
            return false;
        }
        // Expired if the elapsed time since the timestamp exceeds the threshold
        return (now - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, default to expired
        return true;
    }
}

Edge edgeToNext() {
    try {
        // Retrieve the previously returned node and the next node to be returned
        Node prev = this.lastReturnedNode;
        Node next = this.nextNode;

        // Validate that both nodes are available
        if (prev == null || next == null) {
            throw new IllegalStateException("Previous or next node is null");
        }

        // Resolve virtual nodes to their real counterparts if necessary
        Node realPrev = prev.isVirtual() ? prev.getRealNode() : prev;
        Node realNext = next.isVirtual() ? next.getRealNode() : next;

        // Ensure the resolved nodes are not null
        if (realPrev == null || realNext == null) {
            throw new IllegalStateException("Real counterpart of a virtual node is null");
        }

        // Construct and return the edge connecting the two nodes
        return new Edge(realPrev, realNext);
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception with context
        throw new RuntimeException("Failed to create edge to next node", e);
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Handle null inputs
    if (str == null || substring == null) {
        return false;
    }

    int strLen = str.length();
    int subLen = substring.length();

    // Empty substring matches at any valid index (including at the end of the string)
    if (subLen == 0) {
        return index >= 0 && index <= strLen;
    }

    // Index must be within bounds to accommodate the substring
    if (index < 0 || index > strLen - subLen) {
        return false;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

