public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile() || !file.canRead()) {
        throw new IOException("File is null, does not exist, or is not readable: " + file);
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges list cannot be null");
    }
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader(file));
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot = null;
            // Attempt to parse snapshot via static method or constructor
            try {
                Method parseMethod = ThreadSnapshot.class.getMethod("parseFromString", String.class);
                snapshot = (ThreadSnapshot) parseMethod.invoke(null, line);
            } catch (NoSuchMethodException e) {
                try {
                    Constructor<?> ctor = ThreadSnapshot.class.getConstructor(String.class);
                    snapshot = (ThreadSnapshot) ctor.newInstance(line);
                } catch (Exception ex) {
                    // Skip this line if cannot parse
                    continue;
                }
            } catch (Exception e) {
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            // Retrieve timestamp from snapshot
            long ts = 0;
            try {
                Method getTs = ThreadSnapshot.class.getMethod("getTimestamp");
                Object tsObj = getTs.invoke(snapshot);
                if (tsObj instanceof Number) {
                    ts = ((Number) tsObj).longValue();
                } else {
                    continue;
                }
            } catch (Exception e) {
                continue;
            }
            // Check if timestamp falls within any provided time range
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                try {
                    Method getStart = ProfileAnalyzeTimeRange.class.getMethod("getStart");
                    Method getEnd = ProfileAnalyzeTimeRange.class.getMethod("getEnd");
                    Object startObj = getStart.invoke(range);
                    Object endObj = getEnd.invoke(range);
                    if (!(startObj instanceof Number) || !(endObj instanceof Number)) {
                        continue;
                    }
                    long start = ((Number) startObj).longValue();
                    long end = ((Number) endObj).longValue();
                    if (ts >= start && ts <= end) {
                        inRange = true;
                        break;
                    }
                } catch (Exception e) {
                    // Skip this range if any issue
                    continue;
                }
            }
            if (inRange) {
                result.add(snapshot);
            }
        }
    } finally {
        if (reader != null) {
            try {
                reader.close();
            } catch (IOException ignored) {
            }
        }
    }
    return result;
}
